from typing import List

def unalignedDedupe(strings: List[str], m: int, k: int) -> List[int]:
    best_l, best_saved = k, -1
    for l in range(k, m + 1):
        saved = 0
        prev = ''                     # 之前所有串，用 '#' 隔开，防止跨串匹配
        for s in strings:
            for p in range(0, len(s), l):
                b = s[p:p + l]        # 最后一块可能短于 l
                if b in prev or b in s[:p]:
                    saved += len(b)
            prev += s + '#'
        if saved > best_saved:        # 严格大于：并列时保留更小的 l
            best_l, best_saved = l, saved
    # ponytail: 子串查找是 O(总长) 的朴素做法，最坏 O(n·m²)；数据大时换后缀数组 + LCP
    return [best_l, best_saved]
